    private static readonly ConcurrentDictionary<(Glyph, int), BitmapImage?> Cache = new();

    // The pictogram at px x px, in white. Null when there is none or Skia could not read it.
    public static BitmapImage? Image(Glyph glyph, int px) =>
        Cache.GetOrAdd((glyph, px), key => Paths.ContainsKey(key.Item1) && BitmapImage.TryCreateFromSvg(Svg(key.Item1, key.Item2), out var image) ? image : null);

    public static string Svg(Glyph glyph, int px) =>
        $"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{px}\" height=\"{px}\" viewBox=\"0 0 16 16\"><path fill=\"#FFFFFF\" stroke=\"#FFFFFF\" stroke-width=\"0.5\" stroke-linejoin=\"round\" d=\"{Paths[glyph]}\"/></svg>";
}
